ALTER TABLE shop_private.chest_policy_041 ENABLE ROW LEVEL SECURITY;
ALTER TABLE shop_private.content_041 ENABLE ROW LEVEL SECURITY;
ALTER TABLE shop_private.policy_041 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON shop_private.chest_policy_041,shop_private.content_041,shop_private.policy_041 FROM PUBLIC,anon,authenticated,service_role;

-- Existing inventory and ledger remain the only possessions and financial records.
ALTER TABLE public.inventory DROP CONSTRAINT inventory_card_provenance;
ALTER TABLE public.inventory ADD CONSTRAINT inventory_card_provenance CHECK(
 (card_receipt_id IS NULL AND card_version IS NULL) OR
 (card_receipt_id IS NOT NULL AND card_version IS NOT NULL AND
  (quantity=1 OR (quantity>1 AND item_id LIKE 'arena-card-%' AND metadata->>'contract' IS NOT DISTINCT FROM 'economy041-chest-v1'))));
ALTER TABLE public.chest_operations DROP CONSTRAINT chest_operations_type_check;
ALTER TABLE public.chest_operations ADD CONSTRAINT chest_operations_type_check CHECK(
 (((operation_type = ANY (ARRAY['grant'::text, 'purchase'::text, 'open'::text])) AND (chest_type IS NOT NULL)) OR ((operation_type = ANY (ARRAY['card-starter'::text, 'card-revocation'::text, 'arena-result'::text, 'tower-result'::text, 'community-xp'::text])) AND (chest_type IS NULL)) OR ((operation_type = 'equipment-purchase'::text) AND (chest_type IS NULL) AND (source = 'shop001c:equipment'::text) AND (account_id IS NOT NULL) AND (price_paid IS NOT NULL) AND ((rewards ->> 'catalogVersion'::text) = 'ECONOMY-001C:shop:v1'::text) AND (rewards ? 'itemId'::text)) OR ((operation_type = 'equipment-purchase'::text) AND (chest_type IS NULL) AND (source = 'qa-shop001c'::text) AND (account_id IS NOT NULL) AND (price_paid IS NOT NULL) AND ((rewards ->> 'catalogVersion'::text) = 'QA-SHOP-001C:v1'::text) AND (rewards ? 'itemId'::text)) OR ((operation_type = 'administrative-reconciliation'::text) AND (chest_type IS NULL) AND (account_id IS NOT NULL) AND (price_paid IS NULL) AND (source = 'legacy-admin-010'::text) AND ((rewards ->> 'contract'::text) = 'RPG-ECONOMY-FIX-010:v1'::text)) OR ((operation_type = 'economic-initialization'::text) AND (chest_type IS NULL) AND (price_paid = 0) AND (account_id IS NOT NULL) AND (source = 'economic-init-012'::text) AND ((rewards ->> 'contract'::text) = 'RPG-ECONOMY-FIX-012:v1'::text) AND ((rewards ->> 'baselineCoins'::text) = '0'::text) AND ((rewards ->> 'baselineXP'::text) = '0'::text))) OR
 (operation_type='duplicate-sale-041' AND chest_type IS NULL AND account_id IS NOT NULL AND price_paid=0
  AND source='economy041:sale' AND rewards->>'catalogVersion'='economy041-chest-v1' AND rewards ? 'itemId')
);
CREATE FUNCTION shop_private.immutable_041() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
BEGIN RAISE EXCEPTION 'ECONOMY-041 audit is immutable' USING ERRCODE='42501';END $$;
CREATE TRIGGER content041_immutable BEFORE UPDATE OR DELETE ON shop_private.content_041 FOR EACH ROW EXECUTE FUNCTION shop_private.immutable_041();
CREATE TRIGGER chest_policy041_immutable BEFORE UPDATE OR DELETE ON shop_private.chest_policy_041 FOR EACH ROW EXECUTE FUNCTION shop_private.immutable_041();
CREATE TRIGGER receipt041_immutable BEFORE UPDATE OR DELETE ON public.chest_operations FOR EACH ROW
 WHEN(OLD.source LIKE 'economy041:%') EXECUTE FUNCTION shop_private.immutable_041();

CREATE FUNCTION shop_private.random_index_041(p_count integer) RETURNS integer LANGUAGE plpgsql VOLATILE SET search_path='' AS $$
DECLARE bytes bytea; n bigint; ceiling bigint;BEGIN
 IF p_count IS NULL OR p_count<1 OR p_count>100000 THEN RAISE EXCEPTION 'Invalid random bound' USING ERRCODE='22023';END IF;
 ceiling:=(4294967296::bigint/p_count)*p_count;
 LOOP
  bytes:=extensions.gen_random_bytes(4);
  n:=get_byte(bytes,0)::bigint*16777216+get_byte(bytes,1)::bigint*65536+get_byte(bytes,2)::bigint*256+get_byte(bytes,3);
  IF n<ceiling THEN RETURN (n%p_count)::integer;END IF;
 END LOOP;
END $$;
CREATE FUNCTION shop_private.pool_ready_041(p_type text) RETURNS boolean LANGUAGE sql STABLE SET search_path='' AS $$
 SELECT EXISTS(SELECT 1 FROM shop_private.policy_041 WHERE enabled AND singleton)
 AND EXISTS(SELECT 1 FROM shop_private.chest_policy_041 p WHERE p.chest_type=p_type
  AND (SELECT count(*) FROM shop_private.content_041 c WHERE c.rarity=p.rarity AND c.kind='card')=
   CASE p_type WHEN 'common' THEN 3 WHEN 'uncommon' THEN 10 WHEN 'rare' THEN 9 WHEN 'epic' THEN 7 WHEN 'extraordinary' THEN 4 END
  AND (SELECT count(*) FROM shop_private.content_041 c WHERE c.rarity=p.rarity AND c.kind='equipment')=
   CASE p_type WHEN 'common' THEN 8 WHEN 'uncommon' THEN 9 WHEN 'rare' THEN 7 WHEN 'epic' THEN 7 WHEN 'extraordinary' THEN 3 END
  AND NOT EXISTS(SELECT 1 FROM shop_private.content_041 c WHERE c.rarity=p.rarity AND c.kind='card'
   AND NOT EXISTS(SELECT 1 FROM economy_private.card_catalog cc WHERE cc.id=c.item_id AND cc.version=c.version
    AND cc.revoked_at IS NULL AND md5(cc.definition::text)=c.definition_hash)))
$$;
CREATE FUNCTION shop_private.ready_041(p_actor uuid,p_operation uuid) RETURNS uuid LANGUAGE plpgsql SET search_path='' AS $$
DECLARE who uuid;BEGIN
 PERFORM pg_advisory_xact_lock(1010,1);who:=shop_private.actor(p_actor);
 IF p_operation IS NULL THEN RAISE EXCEPTION 'Operation required' USING ERRCODE='22023';END IF;
 PERFORM 1 FROM public.wallets WHERE traveler_id=p_actor FOR UPDATE;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM shop_private.policy WHERE singleton AND enabled)
 OR NOT EXISTS(SELECT 1 FROM shop_private.policy_041 WHERE singleton AND enabled)
 OR EXISTS(SELECT 1 FROM shop_private.holds WHERE account_id=who AND traveler_id=p_actor)
 OR NOT shop_private.balance_valid(p_actor) THEN RAISE EXCEPTION 'Economic authorization unavailable' USING ERRCODE='42501';END IF;
 RETURN who;
END $$;
CREATE FUNCTION shop_private.rate_limit_041(p_owner uuid) RETURNS void LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
 IF (SELECT count(*) FROM public.chest_operations WHERE account_id=p_owner AND source LIKE 'economy041:%'
  AND created_at>clock_timestamp()-interval '1 second')>=10 THEN RAISE EXCEPTION 'Aguarde antes de tentar novamente' USING ERRCODE='PT429';END IF;
END $$;
CREATE FUNCTION shop_private.quantity_041(p_owner uuid,p_actor uuid,p_item text) RETURNS integer LANGUAGE sql STABLE SET search_path='' AS $$
 SELECT coalesce(sum(CASE operation_type WHEN 'open' THEN 1 WHEN 'duplicate-sale-041' THEN -1 ELSE 0 END),0)::integer
 FROM public.chest_operations WHERE account_id=p_owner AND traveler_id=p_actor AND source LIKE 'economy041:%'
 AND rewards->>'catalogVersion'='economy041-chest-v1' AND rewards->>'itemId'=p_item
$$;
CREATE FUNCTION shop_private.purchase_041(p_actor uuid,p_type text,p_operation uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE who uuid; prior public.chest_operations; p shop_private.chest_policy_041; src text; rid uuid;BEGIN
 who:=shop_private.ready_041(p_actor,p_operation);
 IF EXISTS(SELECT 1 FROM public.chest_operations WHERE identity_key='shop-purchase:v1:'||who||':'||p_operation) THEN RAISE EXCEPTION 'Purchase contract conflict' USING ERRCODE='22023';END IF;
 SELECT * INTO prior FROM public.chest_operations WHERE identity_key='economy041:purchase:'||who||':'||p_operation;
 IF FOUND THEN
  IF prior.traveler_id<>p_actor OR prior.chest_type IS DISTINCT FROM p_type THEN RAISE EXCEPTION 'Purchase identity conflict' USING ERRCODE='22023';END IF;
  RETURN jsonb_build_object('version',1,'qaOnly',false,'receiptId',prior.id,'kind','chest','offer',p_type,'pricePaid',prior.price_paid,'replayed',true);
 END IF;
 IF NOT coalesce(shop_private.pool_ready_041(p_type),false) THEN RAISE EXCEPTION 'Chest pool unavailable' USING ERRCODE='55000';END IF;
 PERFORM shop_private.rate_limit_041(who);
 SELECT * INTO STRICT p FROM shop_private.chest_policy_041 WHERE chest_type=p_type;
 IF EXISTS(SELECT 1 FROM public.traveler_chests WHERE traveler_id=p_actor AND chest_type=p_type AND(quantity>=9999 OR jsonb_typeof(sources) IS DISTINCT FROM 'array' OR jsonb_array_length(sources)<>quantity)) THEN RAISE EXCEPTION 'Chest inventory requires review' USING ERRCODE='55000';END IF;
 UPDATE public.wallets SET coins=coins-p.price,updated_at=clock_timestamp() WHERE traveler_id=p_actor AND coins>=p.price;
 IF NOT FOUND THEN RAISE EXCEPTION 'Moedas insuficientes' USING ERRCODE='P0001';END IF;
 src:='economy041:'||p_operation;
 INSERT INTO public.traveler_chests(traveler_id,chest_type,quantity,sources) VALUES(p_actor,p_type,1,jsonb_build_array(src))
 ON CONFLICT(traveler_id,chest_type) DO UPDATE SET quantity=public.traveler_chests.quantity+1,sources=public.traveler_chests.sources||EXCLUDED.sources,updated_at=clock_timestamp();
 INSERT INTO public.chest_operations(traveler_id,account_id,identity_key,operation_key,operation_type,chest_type,source,price_paid,rewards)
 VALUES(p_actor,who,'economy041:purchase:'||who||':'||p_operation,'purchase:'||p_operation,'purchase',p_type,src,p.price,
  jsonb_build_object('catalogVersion','economy041-chest-v1','chestType',p_type,'pricePaid',p.price,'coins',0)) RETURNING id INTO rid;
 IF NOT shop_private.balance_valid(p_actor) THEN RAISE EXCEPTION 'Purchase reconciliation failed' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('version',1,'qaOnly',false,'receiptId',rid,'kind','chest','offer',p_type,'pricePaid',p.price,'replayed',false);
END $$;
CREATE FUNCTION shop_private.open_041(p_actor uuid,p_type text,p_operation uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path='' AS $$
DECLARE who uuid; prior public.chest_operations; stack public.traveler_chests; p shop_private.chest_policy_041; item shop_private.content_041;
 src text; idx integer; wanted text; category text; roll integer; prize_coins integer:=0; qty integer:=0; oldqty integer:=0; rid uuid; answer jsonb;
BEGIN
 who:=shop_private.ready_041(p_actor,p_operation);
 SELECT * INTO prior FROM public.chest_operations WHERE traveler_id=p_actor AND operation_key='open:'||p_operation;
 IF FOUND THEN
  IF prior.account_id IS DISTINCT FROM who OR prior.chest_type IS DISTINCT FROM p_type OR prior.operation_type<>'open'
   OR prior.source NOT LIKE 'economy041:%' OR prior.rewards->>'catalogVersion'<>'economy041-chest-v1' THEN RAISE EXCEPTION 'Opening identity conflict' USING ERRCODE='22023';END IF;
  RETURN prior.rewards||jsonb_build_object('duplicate',true);
 END IF;
 IF NOT coalesce(shop_private.pool_ready_041(p_type),false) THEN RAISE EXCEPTION 'Chest pool unavailable' USING ERRCODE='55000';END IF;
 PERFORM shop_private.rate_limit_041(who);
 SELECT * INTO STRICT p FROM shop_private.chest_policy_041 WHERE chest_type=p_type;
 SELECT * INTO stack FROM public.traveler_chests WHERE traveler_id=p_actor AND chest_type=p_type AND quantity>0 FOR UPDATE;
 IF stack.traveler_id IS NULL OR jsonb_array_length(stack.sources)<>stack.quantity THEN RAISE EXCEPTION 'Unopened chest required' USING ERRCODE='42501';END IF;
 SELECT source INTO wanted FROM public.chest_operations WHERE traveler_id=p_actor AND account_id=who
  AND operation_type='purchase' AND operation_key='purchase:'||p_operation AND chest_type=p_type
  AND source='economy041:'||p_operation AND rewards->>'catalogVersion'='economy041-chest-v1';
 SELECT e.value,e.ordinality::integer-1 INTO src,idx FROM jsonb_array_elements_text(stack.sources) WITH ORDINALITY e(value,ordinality)
 WHERE e.value LIKE 'economy041:%' AND(wanted IS NULL OR e.value=wanted)
  AND (SELECT count(*) FROM jsonb_array_elements_text(stack.sources) x(value) WHERE x.value=e.value)=1
  AND EXISTS(SELECT 1 FROM public.chest_operations r WHERE r.traveler_id=p_actor AND r.account_id=who AND r.chest_type=p_type
   AND r.source=e.value AND r.operation_type IN('purchase','grant') AND r.rewards->>'catalogVersion'='economy041-chest-v1')
  AND NOT EXISTS(SELECT 1 FROM public.chest_operations r WHERE r.traveler_id=p_actor AND r.operation_type='open' AND r.source=e.value)
 ORDER BY e.ordinality LIMIT 1;
 IF src IS NULL THEN RAISE EXCEPTION 'Authorized unconsumed chest required' USING ERRCODE='42501';END IF;
 SELECT * INTO prior FROM public.chest_operations WHERE traveler_id=p_actor AND account_id=who AND source=src AND operation_type='grant';
 IF FOUND AND prior.rewards->>'eventKind'='mission' AND NOT EXISTS(
  SELECT 1 FROM public.guild_missions m JOIN public.guilds g ON g.id=m.guild_id AND g.status='active'
  JOIN public.guild_mission_progress gp ON gp.mission_id=m.id AND gp.traveler_id=p_actor AND gp.participant_uid=who
  WHERE m.id::text=prior.rewards->>'eventId' AND m.status IN('published','closed') AND gp.status='approved'
   AND gp.community_revision::text=prior.rewards->>'approvalRevision' AND gp.approved_by_traveler_id::text=prior.rewards->>'validatorId'
   AND g.leader_traveler_id=gp.approved_by_traveler_id AND economy_private.community_chest_validator(gp.approved_by_traveler_id,m.id)
 ) THEN RAISE EXCEPTION 'Mission reward source unavailable' USING ERRCODE='42501';END IF;
 roll:=shop_private.random_index_041(100);
 category:=CASE WHEN roll<p.coin_weight THEN 'coins' WHEN roll<p.coin_weight+p.card_weight THEN 'card' ELSE 'equipment' END;
 IF category='coins' THEN prize_coins:=p.coin_prize;
 ELSE
  SELECT * INTO STRICT item FROM shop_private.content_041 WHERE rarity=p.rarity AND kind=category ORDER BY item_id
   OFFSET shop_private.random_index_041((SELECT count(*)::integer FROM shop_private.content_041 WHERE rarity=p.rarity AND kind=category)) LIMIT 1;
  SELECT quantity INTO oldqty FROM public.inventory WHERE traveler_id=p_actor AND item_id=item.item_id FOR UPDATE;
  oldqty:=coalesce(oldqty,0);
  IF oldqty<>shop_private.quantity_041(who,p_actor,item.item_id) THEN RAISE EXCEPTION 'Item provenance requires review' USING ERRCODE='42501';END IF;
  IF oldqty>=999 THEN RAISE EXCEPTION 'Inventory quantity limit' USING ERRCODE='55000';END IF;
  qty:=oldqty+1;
 END IF;
 rid:=gen_random_uuid();
 answer:=jsonb_build_object('chestType',p_type,'coins',prize_coins,'itemId',item.item_id,'itemName',item.name,'itemKind',category,
  'cardVersion',item.version,'quantity',qty,'duplicateItem',oldqty>0,'source',src,'remainingQuantity',stack.quantity-1,
  'duplicate',false,'catalogVersion','economy041-chest-v1','sellValue',CASE p.rarity WHEN 'comum' THEN 10 WHEN 'incomum' THEN 20 WHEN 'raro' THEN 35 WHEN 'épico' THEN 70 WHEN 'lendário' THEN 120 END);
 INSERT INTO public.chest_operations(id,traveler_id,account_id,identity_key,operation_key,operation_type,chest_type,source,rewards)
 VALUES(rid,p_actor,who,'economy041:open:'||who||':'||p_operation,'open:'||p_operation,'open',p_type,src,answer);
 IF item.item_id IS NOT NULL THEN
  INSERT INTO public.inventory(traveler_id,item_id,quantity,metadata,card_receipt_id,card_version)
  VALUES(p_actor,item.item_id,1,jsonb_build_object('source',src,'contract','economy041-chest-v1'),CASE WHEN category='card' THEN rid END,item.version)
  ON CONFLICT(traveler_id,item_id) DO UPDATE SET quantity=public.inventory.quantity+1;
 END IF;
 IF stack.quantity=1 THEN DELETE FROM public.traveler_chests WHERE traveler_id=p_actor AND chest_type=p_type;
 ELSE UPDATE public.traveler_chests SET quantity=quantity-1,sources=sources-idx,updated_at=clock_timestamp() WHERE traveler_id=p_actor AND chest_type=p_type;END IF;
 UPDATE public.wallets SET coins=coins+prize_coins,updated_at=clock_timestamp() WHERE traveler_id=p_actor;
 IF NOT shop_private.balance_valid(p_actor) THEN RAISE EXCEPTION 'Opening reconciliation failed' USING ERRCODE='42501';END IF;
 RETURN answer;
END $$;
CREATE FUNCTION shop_private.sell_041(p_actor uuid,p_item text,p_operation uuid,p_expected integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE who uuid;prior public.chest_operations;item shop_private.content_041;qty integer;value integer;answer jsonb;rid uuid;
BEGIN
 who:=shop_private.ready_041(p_actor,p_operation);
 SELECT * INTO prior FROM public.chest_operations WHERE identity_key='economy041:sale:'||who||':'||p_operation;
 IF FOUND THEN
  IF prior.traveler_id<>p_actor OR prior.rewards->>'itemId' IS DISTINCT FROM p_item THEN RAISE EXCEPTION 'Sale identity conflict' USING ERRCODE='22023';END IF;
  RETURN prior.rewards||jsonb_build_object('receiptId',prior.id,'replayed',true);
 END IF;
 SELECT * INTO item FROM shop_private.content_041 WHERE item_id=p_item;
 IF NOT FOUND THEN RAISE EXCEPTION 'Resale source unavailable' USING ERRCODE='42501';END IF;
 SELECT i.quantity INTO qty FROM public.inventory i WHERE traveler_id=p_actor AND item_id=p_item AND card_revoked_at IS NULL AND(to_jsonb(i)->>'arena_qa_receipt_id') IS NULL FOR UPDATE;
 IF qty IS NULL OR qty<2 OR qty<>shop_private.quantity_041(who,p_actor,p_item) THEN RAISE EXCEPTION 'A última cópia deve ser preservada' USING ERRCODE='42501';END IF;
 IF p_expected IS NULL OR qty<>p_expected THEN RAISE EXCEPTION 'A coleção mudou. Atualize antes de vender' USING ERRCODE='PT409';END IF;
 PERFORM shop_private.rate_limit_041(who);
 value:=CASE item.rarity WHEN 'comum' THEN 10 WHEN 'incomum' THEN 20 WHEN 'raro' THEN 35 WHEN 'épico' THEN 70 WHEN 'lendário' THEN 120 END;
 UPDATE public.inventory SET quantity=quantity-1 WHERE traveler_id=p_actor AND item_id=p_item;
 UPDATE public.wallets SET coins=coins+value,updated_at=clock_timestamp() WHERE traveler_id=p_actor;
 answer:=jsonb_build_object('version',1,'catalogVersion','economy041-chest-v1','itemId',p_item,'coins',value,'quantity',qty-1,'replayed',false);
 INSERT INTO public.chest_operations(traveler_id,account_id,identity_key,operation_key,operation_type,source,price_paid,rewards)
 VALUES(p_actor,who,'economy041:sale:'||who||':'||p_operation,'sale:'||p_operation,'duplicate-sale-041','economy041:sale',0,answer) RETURNING id INTO rid;
 IF NOT shop_private.balance_valid(p_actor) THEN RAISE EXCEPTION 'Sale reconciliation failed' USING ERRCODE='42501';END IF;
 RETURN answer||jsonb_build_object('receiptId',rid);
END $$;
CREATE FUNCTION public.sell_repeated_item(p_actor uuid,p_item text,p_operation_id uuid,p_expected_quantity integer) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$
 SELECT shop_private.sell_041(p_actor,p_item,p_operation_id,p_expected_quantity)
$$;
CREATE FUNCTION shop_private.resale_state_041(p_actor uuid,p_item text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE who uuid;qty integer;item shop_private.content_041;BEGIN
 who:=shop_private.actor(p_actor);
 SELECT * INTO item FROM shop_private.content_041 WHERE item_id=p_item;
 SELECT i.quantity INTO qty FROM public.inventory i WHERE traveler_id=p_actor AND item_id=p_item AND card_revoked_at IS NULL AND(to_jsonb(i)->>'arena_qa_receipt_id') IS NULL;
 RETURN jsonb_build_object('version',1,'actor',p_actor,'itemId',p_item,'quantity',coalesce(qty,0),
  'eligible',coalesce(item.item_id IS NOT NULL AND qty>1 AND qty=shop_private.quantity_041(who,p_actor,p_item)
    AND shop_private.balance_valid(p_actor) AND EXISTS(SELECT 1 FROM shop_private.policy_041 WHERE singleton AND enabled)
    AND EXISTS(SELECT 1 FROM shop_private.policy WHERE singleton AND enabled)
    AND NOT EXISTS(SELECT 1 FROM shop_private.holds WHERE traveler_id=p_actor AND account_id=who),false),
  'sellValue',CASE item.rarity WHEN 'comum' THEN 10 WHEN 'incomum' THEN 20 WHEN 'raro' THEN 35 WHEN 'épico' THEN 70 WHEN 'lendário' THEN 120 ELSE 0 END);
END $$;
CREATE FUNCTION public.get_repeated_item_access(p_actor uuid,p_item text) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$ SELECT shop_private.resale_state_041(p_actor,p_item) $$;
REVOKE ALL ON FUNCTION shop_private.resale_state_041(uuid,text),public.get_repeated_item_access(uuid,text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION shop_private.resale_state_041(uuid,text),public.get_repeated_item_access(uuid,text) TO authenticated;
CREATE TABLE shop_private.reward_policy_041(kind text NOT NULL CHECK(kind IN('mission','world')),event_key text NOT NULL,coins integer NOT NULL CHECK(coins>=0),chest_type text NOT NULL REFERENCES shop_private.chest_policy_041(chest_type),PRIMARY KEY(kind,event_key));
ALTER TABLE shop_private.reward_policy_041 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON shop_private.reward_policy_041 FROM PUBLIC,anon,authenticated,service_role;
INSERT INTO shop_private.reward_policy_041 VALUES
 ('mission','normal',25,'common'),('mission','great',100,'uncommon'),('mission','epic',220,'rare'),('mission','extraordinary',360,'epic'),
 ('world','origins',30,'common'),('world','patriarchs',45,'common'),('world','liberation',60,'uncommon'),('world','promised-land',80,'uncommon'),
 ('world','kings',100,'rare'),('world','return',125,'rare'),('world','jesus',150,'epic'),('world','church',180,'epic'),('world','new-creation',220,'extraordinary');
CREATE TRIGGER reward_policy041_immutable BEFORE UPDATE OR DELETE ON shop_private.reward_policy_041 FOR EACH ROW EXECUTE FUNCTION shop_private.immutable_041();
CREATE FUNCTION shop_private.reward_041(p_actor uuid,p_kind text,p_event text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE who uuid;since timestamptz;prior public.chest_operations;policy shop_private.reward_policy_041;
 m public.guild_missions;progress public.guild_mission_progress;attempt public.guild_mission_attempts;g public.guilds;reviewer public.travelers;
 validation guild_activity_private.validation_history;detail guild_activity_private.details;
 rid uuid;source_value text;k text;event_identity text;answer jsonb;d public.story_definitions;s public.story_progress;steps text[];
BEGIN
 -- The immutable event, not a client nonce or selected avatar, identifies the grant globally for Auth.
 who:=shop_private.ready_041(p_actor,gen_random_uuid());
 IF p_kind IS NULL OR p_kind NOT IN('mission','world') OR p_event IS NULL OR length(p_event)>80 THEN RAISE EXCEPTION 'Reward event denied' USING ERRCODE='22023';END IF;
 event_identity:=p_event;
 IF p_kind='mission' THEN
  PERFORM guild_admin_private.require_writes();
  IF p_event !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RAISE EXCEPTION 'Mission identity required' USING ERRCODE='22023';END IF;
  SELECT * INTO m FROM public.guild_missions WHERE id=p_event::uuid FOR UPDATE;
  SELECT * INTO detail FROM guild_activity_private.details WHERE mission_id=m.id FOR SHARE;
  event_identity:=coalesce(detail.meeting_id,m.id)::text;
 END IF;
 k:='economy041:'||p_kind||':'||who||':'||event_identity;
 SELECT * INTO prior FROM public.chest_operations WHERE identity_key=k;
 IF FOUND THEN
  IF prior.traveler_id<>p_actor OR prior.rewards->>'eventId' IS DISTINCT FROM p_event THEN RAISE EXCEPTION 'Reward belongs to original avatar and activity' USING ERRCODE='42501';END IF;
  RETURN prior.rewards||jsonb_build_object('receiptId',prior.id,'replayed',true);
 END IF;
 SELECT activated_at INTO STRICT since FROM shop_private.policy_041 WHERE singleton AND enabled;
 IF p_kind='mission' THEN
  IF p_event !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RAISE EXCEPTION 'Mission identity required' USING ERRCODE='22023';END IF;
  IF m.id IS NULL OR m.community_protocol IS DISTINCT FROM 1 OR m.metadata->'economy041'->>'contract' IS DISTINCT FROM 'economy041-chest-v1'
   OR m.metadata->'economy041'->>'tier' IS DISTINCT FROM m.reward_tier OR detail.kind IS DISTINCT FROM 'activity' OR detail.future_category IS DISTINCT FROM 'none'
   OR(detail.meeting_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.guild_missions WHERE id=detail.meeting_id AND status IN('published','closed')))
   OR m.status NOT IN('published','closed') OR m.published_at IS NULL OR m.published_at<since
   OR NOT m.requires_leader_approval THEN RAISE EXCEPTION 'Mission not eligible for ECONOMY-041' USING ERRCODE='55000';END IF;
  PERFORM guild_ops.actor(p_actor,m.guild_id);
  SELECT * INTO g FROM public.guilds WHERE id=m.guild_id AND status='active' FOR SHARE;
  SELECT * INTO progress FROM public.guild_mission_progress WHERE mission_id=m.id AND traveler_id=p_actor FOR UPDATE;
  SELECT * INTO attempt FROM public.guild_mission_attempts WHERE mission_id=m.id AND traveler_id=p_actor AND revision=progress.submission_revision FOR SHARE;
  SELECT * INTO validation FROM guild_activity_private.validation_history WHERE mission_id=m.id AND traveler_id=p_actor AND revision=progress.community_revision FOR SHARE;
  SELECT * INTO reviewer FROM public.travelers WHERE id=attempt.reviewer_traveler_id FOR SHARE;
  PERFORM 1 FROM auth.users WHERE id=reviewer.user_id AND NOT coalesce(is_anonymous,false) AND email_confirmed_at IS NOT NULL
   AND deleted_at IS NULL AND(banned_until IS NULL OR banned_until<=clock_timestamp()) FOR SHARE;
  IF NOT FOUND OR reviewer.user_id=who OR progress.participant_uid IS DISTINCT FROM who OR progress.status IS DISTINCT FROM 'approved' OR progress.reward_claimed_at IS NOT NULL
   OR validation.after_status IS DISTINCT FROM 'approved' OR validation.reviewer_id IS DISTINCT FROM reviewer.id
   OR NOT EXISTS(SELECT 1 FROM guild_activity_private.future_eligibility WHERE mission_id=m.id AND owner_id=who AND traveler_id=p_actor AND participation_revision=progress.community_revision AND validated AND category='none')
   OR progress.approved_at IS NULL OR progress.approved_at<since OR progress.approved_by_traveler_id IS DISTINCT FROM attempt.reviewer_traveler_id
   OR attempt.decision IS DISTINCT FROM 'approved' OR attempt.decided_at IS NULL OR attempt.decided_at<since OR length(btrim(coalesce(attempt.note,'')))=0
   OR g.leader_traveler_id IS DISTINCT FROM reviewer.id OR NOT guild_admin_private.leader_not_revoked(reviewer.id)
   OR NOT EXISTS(SELECT 1 FROM public.guild_members WHERE guild_id=g.id AND traveler_id=reviewer.id AND role='leader' AND status='active')
   OR EXISTS(SELECT 1 FROM public.guild_reward_claims c JOIN public.travelers t ON t.id=c.traveler_id WHERE c.mission_id=m.id AND t.user_id=who)
   THEN RAISE EXCEPTION 'Current independent leader approval required' USING ERRCODE='42501';END IF;
  SELECT * INTO policy FROM shop_private.reward_policy_041 WHERE kind='mission' AND event_key=m.reward_tier;
 ELSE
  SELECT * INTO policy FROM shop_private.reward_policy_041 WHERE kind='world' AND event_key=p_event;
  IF policy.kind IS NULL OR NOT EXISTS(SELECT 1 FROM public.story_definitions WHERE world_id=p_event) THEN RAISE EXCEPTION 'Published world required' USING ERRCODE='55000';END IF;
  FOR d IN SELECT * FROM public.story_definitions WHERE world_id=p_event ORDER BY narrative_order FOR SHARE LOOP
   IF NOT(d.content_ready AND d.video_ready AND d.reward_ready) THEN RAISE EXCEPTION 'Published content and verified video unavailable' USING ERRCODE='55000';END IF;
   SELECT * INTO s FROM public.story_progress WHERE traveler_id=p_actor AND story_id=d.id FOR SHARE;
   IF s.completed_at IS NULL OR s.completed_at<since OR NOT s.video_completed OR NOT s.completed_steps @> d.required_steps
    THEN RAISE EXCEPTION 'Current official story completion required' USING ERRCODE='55000';END IF;
   SELECT array_agg(step) INTO steps FROM story_private.step_receipts r WHERE r.traveler_id=p_actor AND r.story_id=d.id AND r.revision=d.revision AND r.created_at>=since
    AND((step='video' AND source='provider-api' AND observed_seconds>=duration_seconds AND duration_seconds>0)
     OR(step IN('explore','reading','activity','quiz','reflection') AND source='server-activity')
     OR(step='reward' AND source='economic-ledger' AND EXISTS(SELECT 1 FROM public.chest_operations o WHERE o.id::text=r.proof_reference AND o.traveler_id=p_actor AND o.account_id=who)));
   IF steps IS NULL OR NOT steps @> d.required_steps THEN RAISE EXCEPTION 'Server evidence and provider-verified video required' USING ERRCODE='55000';END IF;
  END LOOP;
 END IF;
 IF policy.kind IS NULL OR NOT coalesce(shop_private.pool_ready_041(policy.chest_type),false) THEN RAISE EXCEPTION 'Reward pool unavailable' USING ERRCODE='55000';END IF;
 PERFORM shop_private.rate_limit_041(who);
 rid:=gen_random_uuid();source_value:='economy041:'||p_kind||':'||rid;
 answer:=jsonb_build_object('version',1,'catalogVersion','economy041-chest-v1','eventKind',p_kind,'eventId',p_event,'coins',policy.coins,'chestType',policy.chest_type,'quantityAdded',1,'replayed',false);
 IF p_kind='mission' THEN answer:=answer||jsonb_build_object('approvalRevision',progress.community_revision,'validatorId',reviewer.id,'approvalReference',validation.request_id);END IF;
 INSERT INTO public.chest_operations(id,traveler_id,account_id,identity_key,operation_key,operation_type,chest_type,source,rewards)
 VALUES(rid,p_actor,who,k,'reward:'||rid,'grant',policy.chest_type,source_value,answer);
 UPDATE public.wallets SET coins=coins+policy.coins,updated_at=clock_timestamp() WHERE traveler_id=p_actor;
 INSERT INTO public.traveler_chests(traveler_id,chest_type,quantity,sources) VALUES(p_actor,policy.chest_type,1,jsonb_build_array(source_value))
 ON CONFLICT(traveler_id,chest_type) DO UPDATE SET quantity=public.traveler_chests.quantity+1,sources=public.traveler_chests.sources||EXCLUDED.sources,updated_at=clock_timestamp();
 IF p_kind='mission' THEN
  INSERT INTO public.guild_reward_claims(mission_id,traveler_id,reward_tier,xp_awarded,coins_awarded) VALUES(m.id,p_actor,m.reward_tier,0,policy.coins);
  UPDATE public.guild_mission_progress SET reward_claimed_at=clock_timestamp() WHERE id=progress.id;
 END IF;
 IF NOT shop_private.balance_valid(p_actor) THEN RAISE EXCEPTION 'Reward reconciliation failed' USING ERRCODE='42501';END IF;
 RETURN answer||jsonb_build_object('receiptId',rid);
END $$;
CREATE FUNCTION public.claim_progress_reward(p_actor uuid,p_kind text,p_event text) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$ SELECT shop_private.reward_041(p_actor,p_kind,p_event) $$;
REVOKE ALL ON FUNCTION shop_private.reward_041(uuid,text,text),public.claim_progress_reward(uuid,text,text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION shop_private.reward_041(uuid,text,text),public.claim_progress_reward(uuid,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION shop_private.purchase(p_actor uuid, p_kind text, p_offer text, p_operation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE who uuid;prior public.chest_operations;answer jsonb;price integer;receipt uuid;k text;source_value text;BEGIN
 PERFORM pg_advisory_xact_lock(1010,1);who:=shop_private.actor(p_actor);
 IF EXISTS(SELECT 1 FROM public.chest_operations WHERE identity_key='economy041:purchase:'||who||':'||p_operation) THEN RAISE EXCEPTION 'Purchase contract conflict' USING ERRCODE='22023';END IF;
 IF p_operation IS NULL OR p_kind IS NULL OR p_offer IS NULL OR NOT((p_kind='chest' AND p_offer='common') OR(p_kind='equipment' AND p_offer IN('traveler-sword-common','traveler-armor-uncommon','traveler-shield-rare'))) THEN RAISE EXCEPTION 'Reviewed offer required' USING ERRCODE='22023';END IF;
 k:='shop-purchase:v1:'||who||':'||p_operation;SELECT * INTO prior FROM public.chest_operations WHERE identity_key=k;
 IF FOUND THEN IF prior.traveler_id<>p_actor OR(p_kind='chest' AND(prior.operation_type<>'purchase' OR prior.chest_type<>p_offer)) OR(p_kind='equipment' AND(prior.operation_type<>'equipment-purchase' OR prior.rewards->>'itemId' IS DISTINCT FROM p_offer)) THEN RAISE EXCEPTION 'Purchase identity conflict' USING ERRCODE='22023';END IF;RETURN jsonb_build_object('version',1,'qaOnly',false,'receiptId',prior.id,'kind',p_kind,'offer',p_offer,'pricePaid',prior.price_paid,'replayed',true);END IF;
 IF NOT EXISTS(SELECT 1 FROM shop_private.policy WHERE singleton AND enabled) THEN RAISE EXCEPTION 'Shop disabled' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM public.wallets WHERE traveler_id=p_actor FOR UPDATE;
 IF EXISTS(SELECT 1 FROM shop_private.holds WHERE account_id=who AND traveler_id=p_actor) OR NOT shop_private.balance_valid(p_actor) THEN RETURN shop_private.hold(who,p_actor,p_operation,'balance-inconsistent');END IF;
 IF p_kind='chest' THEN answer:=economy_private.purchase_chest(p_actor,'common',p_operation);price:=40;source_value:='shop001c:'||p_operation;
 UPDATE public.traveler_chests SET sources=jsonb_set(sources,ARRAY[(quantity-1)::text],to_jsonb(source_value),false) WHERE traveler_id=p_actor AND chest_type='common';
 UPDATE public.chest_operations SET account_id=who,identity_key=k,source=source_value,rewards=rewards||jsonb_build_object('catalogVersion','ECONOMY-001C:shop:v1') WHERE traveler_id=p_actor AND operation_key='purchase:'||p_operation RETURNING id INTO receipt;
 ELSE answer:=economy_private.base_authority(who,p_actor,'purchase',jsonb_build_object('itemId',p_offer));price:=CASE WHEN answer->>'status'='owned' THEN 0 ELSE CASE p_offer WHEN 'traveler-sword-common' THEN 35 WHEN 'traveler-armor-uncommon' THEN 65 WHEN 'traveler-shield-rare' THEN 115 END END;
 INSERT INTO public.chest_operations(traveler_id,account_id,identity_key,operation_key,operation_type,chest_type,source,price_paid,rewards) VALUES(p_actor,who,k,'equipment-purchase:'||p_operation,'equipment-purchase',NULL,'shop001c:equipment',price,jsonb_build_object('itemId',p_offer,'catalogVersion','ECONOMY-001C:shop:v1','status',answer->>'status')) RETURNING id INTO receipt;END IF;
 IF receipt IS NULL OR NOT shop_private.balance_valid(p_actor) THEN RAISE EXCEPTION 'Purchase reconciliation failed' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('version',1,'qaOnly',false,'receiptId',receipt,'kind',p_kind,'offer',p_offer,'pricePaid',price,'replayed',false);END $function$
;
CREATE OR REPLACE FUNCTION shop_private.open(p_actor uuid, p_type text, p_operation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE who uuid;prior public.chest_operations;c public.traveler_chests;answer jsonb;chosen text;position_index integer;remaining jsonb;wanted text;BEGIN
 PERFORM pg_advisory_xact_lock(1010,1);who:=shop_private.actor(p_actor);
 IF EXISTS(SELECT 1 FROM public.chest_operations WHERE traveler_id=p_actor AND account_id=who AND (operation_key='open:'||p_operation OR operation_key='purchase:'||p_operation) AND source LIKE 'economy041:%')
 OR(EXISTS(SELECT 1 FROM public.traveler_chests stack041 CROSS JOIN LATERAL jsonb_array_elements_text(stack041.sources) s(value) WHERE stack041.traveler_id=p_actor AND stack041.chest_type=p_type AND s.value LIKE 'economy041:%')
 AND NOT EXISTS(SELECT 1 FROM public.traveler_chests WHERE traveler_id=p_actor AND chest_type=p_type AND sources->>0 LIKE 'community001c:%')
 AND NOT EXISTS(SELECT 1 FROM public.chest_operations WHERE traveler_id=p_actor AND operation_key='purchase:'||p_operation AND source LIKE 'shop001c:%')) THEN RETURN shop_private.open_041(p_actor,p_type,p_operation);END IF;
 IF p_operation IS NULL OR p_type IS NULL OR p_type NOT IN('common','epic') THEN RAISE EXCEPTION 'Reviewed opening required' USING ERRCODE='22023';END IF;
 SELECT * INTO prior FROM public.chest_operations WHERE traveler_id=p_actor AND operation_key='open:'||p_operation;
 IF FOUND THEN IF prior.account_id IS DISTINCT FROM who OR prior.chest_type<>p_type OR prior.operation_type<>'open' OR NOT(prior.source LIKE 'community001c:%' OR prior.source LIKE 'shop001c:%') THEN RAISE EXCEPTION 'Opening identity conflict' USING ERRCODE='22023';END IF;RETURN prior.rewards||jsonb_build_object('duplicate',true);END IF;
 IF NOT EXISTS(SELECT 1 FROM shop_private.policy WHERE singleton AND enabled) THEN RAISE EXCEPTION 'Shop disabled' USING ERRCODE='42501';END IF;
 SELECT * INTO c FROM public.traveler_chests WHERE traveler_id=p_actor AND chest_type=p_type AND quantity>0 FOR UPDATE;
 IF c.traveler_id IS NOT NULL AND c.sources->>0 LIKE 'community001c:%' AND NOT EXISTS(SELECT 1 FROM public.chest_operations WHERE traveler_id=p_actor AND account_id=who AND operation_key='purchase:'||p_operation AND operation_type='purchase' AND source='shop001c:'||p_operation) THEN RETURN economy_private.open_community_chest_001c(p_actor,p_type,p_operation);END IF;
 PERFORM 1 FROM public.wallets WHERE traveler_id=p_actor FOR UPDATE;
 IF EXISTS(SELECT 1 FROM shop_private.holds WHERE account_id=who AND traveler_id=p_actor) OR NOT shop_private.balance_valid(p_actor) THEN RETURN shop_private.hold(who,p_actor,p_operation,'balance-inconsistent');END IF;
 -- Select only an outstanding, unique source backed by this account's purchase.
 -- The existing opener consumes index zero; move the selected source inside the
 -- same transaction, retaining the relative order of every unconsumed source.
 IF p_type='common' AND c.traveler_id IS NOT NULL AND jsonb_array_length(c.sources)=c.quantity THEN
   SELECT source INTO wanted FROM public.chest_operations
    WHERE traveler_id=p_actor AND account_id=who AND operation_type='purchase'
     AND chest_type='common' AND operation_key='purchase:'||p_operation
     AND source='shop001c:'||p_operation AND price_paid=40
     AND rewards->>'catalogVersion'='ECONOMY-001C:shop:v1';
   SELECT e.value,e.ordinality::integer-1 INTO chosen,position_index
    FROM jsonb_array_elements_text(c.sources) WITH ORDINALITY e(value,ordinality)
    WHERE e.value LIKE 'shop001c:%' AND (wanted IS NULL OR e.value=wanted)
     AND (SELECT count(*) FROM jsonb_array_elements_text(c.sources) z(value) WHERE z.value=e.value)=1
     AND EXISTS(SELECT 1 FROM public.chest_operations r WHERE r.traveler_id=p_actor AND r.account_id=who
       AND r.operation_type='purchase' AND r.chest_type='common' AND r.source=e.value
       AND r.operation_key='purchase:'||substring(e.value from 10) AND r.price_paid=40
       AND r.rewards->>'catalogVersion'='ECONOMY-001C:shop:v1')
     AND NOT EXISTS(SELECT 1 FROM public.chest_operations r WHERE r.traveler_id=p_actor
       AND r.operation_type='open' AND r.source=e.value)
    ORDER BY e.ordinality LIMIT 1;
   IF wanted IS NOT NULL AND chosen IS NULL THEN RAISE EXCEPTION 'Purchase already consumed or source unavailable' USING ERRCODE='22023';END IF;
   IF position_index>0 THEN
     remaining:=c.sources-position_index;
     c.sources:=jsonb_build_array(chosen)||remaining;
     UPDATE public.traveler_chests SET sources=c.sources WHERE traveler_id=p_actor AND chest_type=p_type;
   END IF;
 END IF;
 IF chosen IS NULL OR p_type<>'common' OR c.traveler_id IS NULL OR jsonb_array_length(c.sources)<>c.quantity OR(c.sources->>0) NOT LIKE 'shop001c:%' OR NOT EXISTS(SELECT 1 FROM public.chest_operations WHERE traveler_id=p_actor AND account_id=who AND source=c.sources->>0 AND operation_type='purchase' AND chest_type='common' AND price_paid=40 AND rewards->>'catalogVersion'='ECONOMY-001C:shop:v1') THEN RAISE EXCEPTION 'Verified unopened purchase required' USING ERRCODE='42501';END IF;
 answer:=economy_private.open_chest(p_actor,'common',p_operation);
 IF((answer->>'coins'='25' AND answer->>'itemId' IS NULL) OR(answer->>'coins'='10' AND answer->>'itemId'='traveler-sword-common')) IS DISTINCT FROM true THEN RAISE EXCEPTION 'Reviewed common loot required' USING ERRCODE='42501';END IF;
 UPDATE public.chest_operations SET account_id=who,identity_key='shop-open:v1:'||who||':'||p_operation,rewards=rewards||jsonb_build_object('catalogVersion','ECONOMY-001C:shop:v1') WHERE traveler_id=p_actor AND operation_key='open:'||p_operation;
 IF NOT shop_private.balance_valid(p_actor) THEN RAISE EXCEPTION 'Opening reconciliation failed' USING ERRCODE='42501';END IF;RETURN answer;END $function$
;
CREATE OR REPLACE FUNCTION shop_private.coin_balance(p_actor uuid)
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT (SELECT coalesce(sum(CASE WHEN operation_type='purchase' THEN -price_paid::bigint WHEN operation_type IN('open','duplicate-sale-041','grant') THEN (rewards->>'coins')::bigint ELSE 0 END),0) FROM public.chest_operations WHERE traveler_id=p_actor AND account_id=(SELECT user_id FROM public.travelers WHERE id=p_actor) AND source LIKE 'economy041:%' AND rewards->>'catalogVersion'='economy041-chest-v1') + coalesce(sum(CASE WHEN operation_type='open' THEN (rewards->>'coins')::bigint
 WHEN operation_type IN('purchase','equipment-purchase') THEN -price_paid::bigint ELSE 0 END),0)
 +coalesce((SELECT (r.rewards->>'baselineCoins')::bigint FROM public.chest_operations r
 WHERE p_actor='31b70059-deca-44c8-a6df-f21ea68b6e42'::uuid AND r.traveler_id=p_actor AND r.account_id='78729453-8e04-478c-96ae-d37cead1bc8c'::uuid
 AND r.account_id=(SELECT user_id FROM public.travelers WHERE id=p_actor)
 AND r.operation_type='administrative-reconciliation' AND r.source='legacy-admin-010'
 AND r.identity_key='legacy-admin-010:31b70059-deca-44c8-a6df-f21ea68b6e42'
 AND r.rewards->>'contract'='RPG-ECONOMY-FIX-010:v1'
 AND r.rewards->>'approvalRef'='OWNER-APPROVED-2026-11-07'
 AND r.rewards->>'baselineCoins'='1006265'),0)
 +shop_qa_private.fixture_credit_014(p_actor)
 FROM public.chest_operations WHERE traveler_id=p_actor AND account_id=(SELECT user_id FROM public.travelers WHERE id=p_actor)
 AND((operation_type='open' AND source LIKE 'community001c:%') OR(source LIKE 'shop001c:%' AND rewards->>'catalogVersion'='ECONOMY-001C:shop:v1'))
$function$
;
CREATE OR REPLACE FUNCTION shop_private.state(p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE who uuid;reason text;BEGIN
 PERFORM pg_advisory_xact_lock(1010,1);who:=economy_private.community_xp_actor(p_actor);
 IF public.release_scope()<>'hero-equipment-006' OR NOT EXISTS(SELECT 1 FROM shop_private.policy WHERE singleton AND enabled) THEN reason:='disabled';
 ELSIF NOT EXISTS(SELECT 1 FROM public.travelers WHERE id=p_actor AND economic_verified_at IS NOT NULL) THEN reason:='legacy-reconciliation-required';
 ELSIF EXISTS(SELECT 1 FROM public.chest_operations WHERE traveler_id=p_actor AND(source LIKE 'qa-shop001c%' OR coalesce((rewards->>'qaOnly')::boolean,false))) THEN reason:='qa-source';
 ELSIF EXISTS(SELECT 1 FROM shop_private.holds WHERE account_id=who AND traveler_id=p_actor) THEN reason:='suspended';
 ELSIF NOT shop_private.balance_valid(p_actor) THEN reason:='balance-inconsistent';END IF;
 RETURN jsonb_build_object('version',1,'qaOnly',false,'enabled',reason IS NULL,'reason',reason,'coins',(SELECT coins FROM public.wallets WHERE traveler_id=p_actor),'balanceVerified',reason IS NULL,'initializationEligible',coalesce(reason='legacy-reconciliation-required' AND has_function_privilege('authenticated','shop_private.initialize_012(uuid)','EXECUTE') AND shop_private.pristine_012(p_actor),false),'catalogVersion','ECONOMY-001C:shop:v1','expansionVersion',(SELECT contract FROM shop_private.policy_041 WHERE singleton AND enabled),'offers',CASE WHEN EXISTS(SELECT 1 FROM shop_private.policy_041 WHERE singleton AND enabled) THEN jsonb_build_array(
 jsonb_build_object('kind','chest','id','common','price',40),jsonb_build_object('kind','chest','id','uncommon','price',80),jsonb_build_object('kind','chest','id','rare','price',150),jsonb_build_object('kind','chest','id','epic','price',250),jsonb_build_object('kind','chest','id','extraordinary','price',400),jsonb_build_object('kind','equipment','id','traveler-sword-common','price',35),jsonb_build_object('kind','equipment','id','traveler-armor-uncommon','price',65),jsonb_build_object('kind','equipment','id','traveler-shield-rare','price',115)) ELSE jsonb_build_array(
 jsonb_build_object('kind','chest','id','common','price',40),jsonb_build_object('kind','equipment','id','traveler-sword-common','price',35),jsonb_build_object('kind','equipment','id','traveler-armor-uncommon','price',65),jsonb_build_object('kind','equipment','id','traveler-shield-rare','price',115)) END);
END $function$
;
CREATE OR REPLACE FUNCTION shop_private.equipment_origin_014(p_owner uuid, p_actor uuid, p_item text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
BEGIN
 IF p_item IS NULL OR p_item NOT IN(
   'traveler-boots','traveler-helmet-rare','wisdom-amulet','traveler-sword-common','traveler-armor-uncommon','traveler-shield-rare',
   'equipment-apprentice-sword','equipment-pilgrim-blade','equipment-guardian-sword','equipment-courage-blade','equipment-perseverance-sword','equipment-victory-blade',
   'equipment-reinforced-tunic','equipment-traveler-vest','equipment-vigilance-cuirass','equipment-guardian-armor','equipment-perseverance-armor','equipment-fortress-armor',
   'equipment-wooden-shield','equipment-apprentice-shield','equipment-vigilance-shield','equipment-pilgrim-shield','equipment-courage-shield','equipment-fortress-shield',
   'equipment-leather-helmet','equipment-journey-helmet','equipment-vigilance-helmet','equipment-guardian-helmet','equipment-perseverance-helmet',
   'equipment-reinforced-sandals','equipment-explorer-boots','equipment-journey-boots','equipment-pilgrim-boots','equipment-perseverance-boots',
   'equipment-simple-pendant','equipment-journey-medal','equipment-prudence-amulet','equipment-vigilance-medallion','equipment-guardian-medallion','equipment-perseverance-medallion'
 ) THEN RETURN 'catalog-unavailable'; END IF;
 IF EXISTS(SELECT 1 FROM shop_private.content_041 c WHERE c.item_id=p_item AND c.kind='equipment') AND shop_private.quantity_041(p_owner,p_actor,p_item)>0 THEN RETURN NULL;END IF;
 IF p_item<>'traveler-boots' AND NOT EXISTS(
   SELECT 1 FROM public.chest_operations
   WHERE account_id=p_owner AND traveler_id=p_actor AND rewards->>'itemId'=p_item
    AND((operation_type='open' AND source LIKE 'community001c:%')
     OR(operation_type IN('open','equipment-purchase') AND source LIKE 'shop001c:%'
       AND rewards->>'catalogVersion'='ECONOMY-001C:shop:v1'))
  ) AND NOT (
   p_item IN('wisdom-amulet','traveler-helmet-rare') AND EXISTS(
    SELECT 1 FROM economy_private.journey_rewards j
    JOIN public.inventory i ON i.traveler_id=j.traveler_id
    WHERE j.traveler_id=p_actor
     AND j.reward_key=CASE p_item WHEN 'wisdom-amulet' THEN 'phase:garden-choice' ELSE 'garden-equipment' END
     AND i.item_id=p_item AND i.quantity>0 AND i.card_receipt_id IS NULL
     AND i.metadata->>'source'=j.reward_key
   )
  ) THEN RETURN 'acquisition-unconfirmed'; END IF;
 RETURN NULL;
END $function$
;
CREATE OR REPLACE FUNCTION economy_private.collection(p_user uuid, p_traveler uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT coalesce(jsonb_agg(jsonb_build_object('card',c.definition,'version',c.version,'receiptId',r.id,'quantity',i.quantity) ORDER BY c.id),'[]')
 FROM public.inventory i JOIN public.travelers t ON t.id=i.traveler_id
 JOIN public.chest_operations r ON r.id=i.card_receipt_id AND r.traveler_id=t.id AND r.account_id=t.user_id AND(r.operation_type='card-starter' OR(r.operation_type='open' AND r.source LIKE 'economy041:%' AND r.rewards->>'catalogVersion'='economy041-chest-v1' AND r.rewards->>'itemKind'='card' AND r.rewards->>'itemId'=i.item_id))
 JOIN economy_private.card_catalog c ON c.id=i.item_id AND c.version=i.card_version
 WHERE t.id=p_traveler AND t.user_id=p_user AND(i.quantity=1 OR(r.operation_type='open' AND i.quantity=shop_private.quantity_041(p_user,p_traveler,i.item_id))) AND i.card_revoked_at IS NULL AND c.revoked_at IS NULL
 AND((r.operation_type='card-starter' AND r.rewards->'cardIds' ? i.item_id) OR(r.operation_type='open' AND r.rewards->>'itemId'=i.item_id AND i.quantity=shop_private.quantity_041(p_user,p_traveler,i.item_id)));
$function$
;
CREATE OR REPLACE FUNCTION guild_activity_private.command(p_actor uuid, p_guild uuid, p_action text, p_id uuid, p_request uuid, p_revision integer, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE owner_id uuid;own_role text;m public.guild_missions%ROWTYPE;d guild_activity_private.details%ROWTYPE;
 gp public.guild_mission_progress%ROWTYPE;old_cmd guild_activity_private.commands%ROWTYPE;
 old_delegate guild_activity_private.delegations%ROWTYPE;sig text;receipt jsonb;next_rev integer;target uuid;target_owner uuid;actor_name text;
 parent uuid;v_kind text;v_status text;v_category text;v_future text;v_expires timestamptz;v_start timestamptz;v_due timestamptz;v_targets uuid[];v_now timestamptz;previous_status text;
BEGIN
 PERFORM pg_catalog.pg_advisory_xact_lock(1010,1);PERFORM guild_admin_private.require_writes();own_role:=guild_activity_private.actor_role(p_actor,p_guild);owner_id:=auth.uid();v_now:=clock_timestamp();
 IF p_id IS NULL OR p_request IS NULL OR p_revision IS NULL OR p_revision<0 OR jsonb_typeof(p_data) IS DISTINCT FROM 'object' OR p_action IS NULL OR p_action NOT IN('save','state','delegate','participate','review') THEN RAISE EXCEPTION 'Invalid command' USING ERRCODE='22023';END IF;
 SELECT * INTO m FROM public.guild_missions WHERE id=p_id FOR UPDATE;
 IF m.id IS NOT NULL AND(m.guild_id<>p_guild OR m.community_protocol IS DISTINCT FROM 1) THEN RAISE EXCEPTION 'Activity unavailable' USING ERRCODE='42501';END IF;
 IF p_action IN('save','state','delegate') AND own_role<>'leader' OR p_action='review' AND(m.id IS NULL OR NOT guild_activity_private.can_validate(p_actor,p_id)) THEN RAISE EXCEPTION 'Current activity authorization required' USING ERRCODE='42501';END IF;
 IF p_action<>'save' AND m.id IS NULL THEN RAISE EXCEPTION 'Activity unavailable' USING ERRCODE='P0002';END IF;
 sig:=md5(jsonb_build_array(p_actor,p_guild,p_action,p_id,p_revision,p_data)::text);SELECT * INTO old_cmd FROM guild_activity_private.commands WHERE request_id=p_request;
 IF old_cmd.request_id IS NOT NULL THEN IF old_cmd.owner_id<>owner_id OR old_cmd.actor_id<>p_actor OR old_cmd.guild_id<>p_guild OR old_cmd.fingerprint<>sig THEN RAISE EXCEPTION 'Command conflict' USING ERRCODE='PT409';END IF;RETURN old_cmd.receipt||jsonb_build_object('replayed',true);END IF;
 SELECT * INTO d FROM guild_activity_private.details WHERE mission_id=p_id;
 IF p_action='save' THEN
 PERFORM guild_admin_private.exact_keys(p_data,ARRAY['title','description','objective','instructions','evidenceCriterion','bibleReference','startsAt','dueAt','audience','targetIds','kind','meetingId','category','theme','meetingType','responsibleId','accessDetails','futureCategory','economyTier']);
 IF m.id IS NOT NULL AND(m.status<>'draft' OR m.workspace_revision<>p_revision) OR m.id IS NULL AND p_revision<>0 THEN RAISE EXCEPTION 'Activity conflict' USING ERRCODE='PT409';END IF;
 v_kind:=p_data->>'kind';v_category:=p_data->>'category';v_future:=p_data->>'futureCategory';
 IF v_kind IS NULL OR v_kind NOT IN('meeting','activity') OR v_category IS NULL OR v_category NOT IN('biblical_challenge','guided_reading','practical','gincana','solidarity','group','cooperative','competitive','special') OR v_future IS NULL OR v_future NOT IN('none','common','rare','epic')
 OR length(btrim(coalesce(p_data->>'title',''))) NOT BETWEEN 2 AND 100 OR length(btrim(coalesce(p_data->>'description',''))) NOT BETWEEN 1 AND 1000 OR length(btrim(coalesce(p_data->>'objective',''))) NOT BETWEEN 1 AND 500
 OR length(btrim(coalesce(p_data->>'instructions',''))) NOT BETWEEN 1 AND 1000 OR length(btrim(coalesce(p_data->>'evidenceCriterion',''))) NOT BETWEEN 1 AND 300 OR length(coalesce(p_data->>'bibleReference',''))>100 OR length(coalesce(p_data->>'theme',''))>100 OR length(coalesce(p_data->>'accessDetails',''))>600
 OR p_data->>'meetingType' IS NULL OR p_data->>'meetingType' NOT IN('in_person','digital') OR p_data->>'audience' IS NULL OR p_data->>'audience' NOT IN('all','selected') OR jsonb_typeof(p_data->'targetIds') IS DISTINCT FROM 'array' OR jsonb_array_length(p_data->'targetIds')>100 THEN RAISE EXCEPTION 'Invalid activity fields' USING ERRCODE='22023';END IF;
 v_start:=nullif(p_data->>'startsAt','')::timestamptz;v_due:=nullif(p_data->>'dueAt','')::timestamptz;
 IF v_kind='meeting' AND v_start IS NULL OR v_due<=v_start OR v_kind='activity' AND coalesce(p_data->>'accessDetails','')<>'' THEN RAISE EXCEPTION 'Invalid meeting date or access' USING ERRCODE='22023';END IF;
 IF v_kind='meeting' AND p_data->>'meetingType'='digital' AND coalesce(p_data->>'accessDetails','')<>'' AND(p_data->>'accessDetails' !~ '^https://[^/@[:space:]]+([/?#][^[:space:]]*)?$' OR p_data->>'accessDetails'~'[[:cntrl:]]') THEN RAISE EXCEPTION 'HTTPS access link required' USING ERRCODE='22023';END IF;
 SELECT coalesce(array_agg(DISTINCT value::uuid),'{}') INTO v_targets FROM jsonb_array_elements_text(p_data->'targetIds');
 IF p_data->>'audience'='all' AND cardinality(v_targets)>0 OR p_data->>'audience'='selected' AND cardinality(v_targets)=0 OR EXISTS(SELECT 1 FROM unnest(v_targets) t WHERE NOT EXISTS(SELECT 1 FROM public.guild_members gm WHERE gm.guild_id=p_guild AND gm.traveler_id=t AND gm.status='active')) THEN RAISE EXCEPTION 'Invalid audience' USING ERRCODE='42501';END IF;
 target:=(p_data->>'responsibleId')::uuid;IF target IS NULL OR NOT EXISTS(SELECT 1 FROM public.guild_members WHERE guild_id=p_guild AND traveler_id=target AND status='active') THEN RAISE EXCEPTION 'Responsible must be an active member; validation requires explicit delegation' USING ERRCODE='42501';END IF;
 parent:=nullif(p_data->>'meetingId','')::uuid;IF parent IS NOT NULL AND(v_kind<>'activity' OR NOT EXISTS(SELECT 1 FROM public.guild_missions pm JOIN guild_activity_private.details pd ON pd.mission_id=pm.id WHERE pm.id=parent AND pm.guild_id=p_guild AND pm.community_protocol=1 AND pd.kind='meeting' AND pm.status IN('draft','published'))) THEN RAISE EXCEPTION 'Meeting unavailable' USING ERRCODE='42501';END IF;
 IF m.id IS NOT NULL AND d.kind<>v_kind THEN RAISE EXCEPTION 'Activity kind is fixed' USING ERRCODE='22023';END IF;
 next_rev:=coalesce(m.workspace_revision,0)+1;
 INSERT INTO public.guild_missions(id,guild_id,created_by_traveler_id,title,description,mission_type,completion_mode,requires_leader_approval,reward_tier,status,starts_at,due_at,objective,instructions,evidence_criterion,bible_reference,audience,target_traveler_ids,workspace_revision,community_protocol)
 VALUES(p_id,p_guild,p_actor,btrim(p_data->>'title'),p_data->>'description','practical_activity','leader_approval',true,'normal','draft',v_start,v_due,p_data->>'objective',p_data->>'instructions',p_data->>'evidenceCriterion',p_data->>'bibleReference',p_data->>'audience',v_targets,next_rev,1)
 ON CONFLICT(id) DO UPDATE SET title=excluded.title,description=excluded.description,starts_at=excluded.starts_at,due_at=excluded.due_at,objective=excluded.objective,instructions=excluded.instructions,evidence_criterion=excluded.evidence_criterion,bible_reference=excluded.bible_reference,audience=excluded.audience,target_traveler_ids=excluded.target_traveler_ids,workspace_revision=excluded.workspace_revision;
 INSERT INTO guild_activity_private.details VALUES(p_id,v_kind,parent,v_category,coalesce(p_data->>'theme',''),p_data->>'meetingType',target,coalesce(p_data->>'accessDetails',''),v_future)
 ON CONFLICT(mission_id) DO UPDATE SET meeting_id=excluded.meeting_id,category=excluded.category,theme=excluded.theme,meeting_type=excluded.meeting_type,responsible_id=excluded.responsible_id,access_details=excluded.access_details,future_category=excluded.future_category;
 IF p_data ? 'economyTier' THEN
 IF jsonb_typeof(p_data->'economyTier') IS DISTINCT FROM 'string' OR p_data->>'economyTier' NOT IN('none','normal','great','epic','extraordinary')
 OR(p_data->>'economyTier'<>'none' AND(v_kind<>'activity' OR v_future<>'none')) THEN RAISE EXCEPTION 'Choose a single approved reward policy' USING ERRCODE='22023';END IF;
 UPDATE public.guild_missions SET reward_tier=CASE WHEN p_data->>'economyTier'='none' THEN 'normal' ELSE p_data->>'economyTier' END,
 metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('economy041',jsonb_build_object('contract','economy041-chest-v1','tier',p_data->>'economyTier')) WHERE id=p_id;
 END IF;
 ELSIF p_action='state' THEN
 PERFORM guild_admin_private.exact_keys(p_data,ARRAY['state']);v_status:=p_data->>'state';
 IF m.workspace_revision<>p_revision THEN RAISE EXCEPTION 'Activity conflict' USING ERRCODE='PT409';END IF;
 IF NOT(m.status='draft' AND v_status IN('published','cancelled') OR m.status='published' AND v_status IN('closed','cancelled')) THEN RAISE EXCEPTION 'Invalid activity transition' USING ERRCODE='22023';END IF;
 IF v_status='published' AND d.meeting_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.guild_missions WHERE id=d.meeting_id AND status='published') THEN RAISE EXCEPTION 'Publish parent meeting first' USING ERRCODE='22023';END IF;
 IF v_status='closed' AND d.kind='meeting' AND EXISTS(SELECT 1 FROM guild_activity_private.details child JOIN public.guild_missions cm ON cm.id=child.mission_id WHERE child.meeting_id=p_id AND cm.status NOT IN('closed','cancelled')) THEN RAISE EXCEPTION 'Close or cancel meeting activities first' USING ERRCODE='22023';END IF;
 previous_status:=m.status;
 UPDATE public.guild_missions SET status=v_status,workspace_revision=workspace_revision+1,published_at=CASE WHEN v_status='published' THEN v_now ELSE published_at END,closed_at=CASE WHEN v_status IN('closed','cancelled') THEN v_now ELSE closed_at END WHERE id=p_id;next_rev:=p_revision+1;
 IF v_status='cancelled' THEN UPDATE guild_activity_private.future_eligibility SET validated=false,updated_at=v_now WHERE mission_id=p_id OR mission_id IN(SELECT mission_id FROM guild_activity_private.details WHERE meeting_id=p_id);END IF;
 ELSIF p_action='delegate' THEN
 PERFORM guild_admin_private.exact_keys(p_data,ARRAY['travelerId','active','expiresAt']);target:=(p_data->>'travelerId')::uuid;v_expires:=(p_data->>'expiresAt')::timestamptz;
 IF jsonb_typeof(p_data->'active') IS DISTINCT FROM 'boolean' OR target IS NULL OR NOT EXISTS(SELECT 1 FROM public.guild_members WHERE guild_id=p_guild AND traveler_id=target AND status='active') OR (p_data->>'active')::boolean AND m.status NOT IN('draft','published') THEN RAISE EXCEPTION 'Invalid temporary validator' USING ERRCODE='42501';END IF;
 IF v_expires IS NULL OR (p_data->>'active')::boolean AND(v_expires<=v_now OR v_expires>v_now+interval '30 days') THEN RAISE EXCEPTION 'Temporary delegation requires a future expiry within30days' USING ERRCODE='22023';END IF;
 SELECT * INTO old_delegate FROM guild_activity_private.delegations WHERE mission_id=p_id AND traveler_id=target;
 IF coalesce(old_delegate.revision,0)<>p_revision THEN RAISE EXCEPTION 'Delegation conflict' USING ERRCODE='PT409';END IF;next_rev:=p_revision+1;
 INSERT INTO guild_activity_private.delegations VALUES(p_id,target,v_expires,(p_data->>'active')::boolean,next_rev,p_actor) ON CONFLICT(mission_id,traveler_id) DO UPDATE SET expires_at=excluded.expires_at,active=excluded.active,revision=excluded.revision,granted_by=excluded.granted_by;
 ELSIF p_action='participate' THEN
 PERFORM guild_admin_private.exact_keys(p_data,ARRAY['declared']);IF p_data->'declared' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'Participation declaration required; no personal text' USING ERRCODE='22023';END IF;
 IF m.status<>'published' OR m.audience='selected' AND NOT p_actor=ANY(m.target_traveler_ids) OR m.starts_at>v_now OR m.due_at<v_now OR d.meeting_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.guild_missions WHERE id=d.meeting_id AND status='published') THEN RAISE EXCEPTION 'Participation unavailable' USING ERRCODE='42501';END IF;
 SELECT * INTO gp FROM public.guild_mission_progress WHERE mission_id=p_id AND participant_uid=owner_id FOR UPDATE;
 IF gp.id IS NOT NULL AND gp.traveler_id<>p_actor THEN RAISE EXCEPTION 'Account already participating through another avatar' USING ERRCODE='PT409';END IF;
 IF coalesce(gp.community_revision,0)<>p_revision OR gp.status IN('pending_approval','approved','completed') THEN RAISE EXCEPTION 'Participation conflict' USING ERRCODE='PT409';END IF;next_rev:=p_revision+1;
 INSERT INTO public.guild_mission_progress(mission_id,traveler_id,participant_uid,community_revision,status,submitted_at,completion_note,submission_revision)
 VALUES(p_id,p_actor,owner_id,next_rev,'pending_approval',v_now,'ParticipaÃ§Ã£o declarada',1)
 ON CONFLICT(mission_id,traveler_id) DO UPDATE SET community_revision=excluded.community_revision,status='pending_approval',submitted_at=v_now,completion_note='ParticipaÃ§Ã£o declarada',submission_revision=guild_mission_progress.submission_revision+1 RETURNING * INTO gp;
 INSERT INTO public.guild_mission_attempts(mission_id,traveler_id,revision,request_id,note) VALUES(p_id,p_actor,gp.submission_revision,p_request,'ParticipaÃ§Ã£o declarada');
 ELSIF p_action='review' THEN
 PERFORM guild_admin_private.exact_keys(p_data,ARRAY['travelerId','decision','reason']);target:=(p_data->>'travelerId')::uuid;v_status:=p_data->>'decision';
 SELECT user_id INTO target_owner FROM public.travelers WHERE id=target;
 IF target_owner IS NULL OR target_owner=owner_id OR m.status NOT IN('published','closed') OR m.starts_at>v_now OR NOT EXISTS(SELECT 1 FROM public.guild_members WHERE guild_id=p_guild AND traveler_id=target AND status='active') THEN RAISE EXCEPTION 'Cannot validate own account or unavailable participation' USING ERRCODE='42501';END IF;
 IF d.meeting_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.guild_missions WHERE id=d.meeting_id AND status='cancelled') THEN RAISE EXCEPTION 'Parent meeting cancelled' USING ERRCODE='42501';END IF;
 SELECT * INTO gp FROM public.guild_mission_progress WHERE mission_id=p_id AND traveler_id=target AND participant_uid=target_owner FOR UPDATE;
 IF gp.id IS NULL OR gp.community_revision<>p_revision THEN RAISE EXCEPTION 'Participation conflict' USING ERRCODE='PT409';END IF;
 IF v_status IS NULL OR v_status NOT IN('approved','rejected','changes_requested') OR length(coalesce(p_data->>'reason',''))>300 OR (v_status<>'approved' OR gp.status<>'pending_approval' OR m.status='closed') AND length(btrim(coalesce(p_data->>'reason','')))=0 THEN RAISE EXCEPTION 'Objective correction reason required' USING ERRCODE='22023';END IF;
 IF coalesce(p_data->>'reason','') ~* '(bearer[[:space:]]+[a-z0-9._-]+|eyJ[a-z0-9_-]{15,}\.[a-z0-9_-]+|sb_secret_|sbp_|-----BEGIN[[:space:]].*PRIVATE KEY|password[[:space:]]*[:=]|senha[[:space:]]*[:=]|[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,})' THEN RAISE EXCEPTION 'Do not include credentials or personal contacts in correction reason' USING ERRCODE='22023';END IF;
 previous_status:=gp.status;next_rev:=p_revision+1;
 UPDATE public.guild_mission_progress SET status=v_status,community_revision=next_rev,review_note=coalesce(p_data->>'reason',''),approved_at=CASE WHEN v_status='approved' THEN v_now ELSE NULL END,approved_by_traveler_id=CASE WHEN v_status='approved' THEN p_actor ELSE NULL END WHERE id=gp.id;
 UPDATE public.guild_mission_attempts SET decision=v_status,reason=coalesce(p_data->>'reason',''),reviewer_traveler_id=p_actor,decided_at=v_now,decision_request_id=p_request WHERE mission_id=p_id AND traveler_id=target AND revision=gp.submission_revision;
 INSERT INTO guild_activity_private.validation_history(request_id,mission_id,traveler_id,reviewer_id,before_status,after_status,reason,revision) VALUES(p_request,p_id,target,p_actor,previous_status,v_status,coalesce(p_data->>'reason',''),next_rev);
 INSERT INTO guild_activity_private.future_eligibility(mission_id,owner_id,traveler_id,category,participation_revision,validated) VALUES(p_id,target_owner,target,d.future_category,next_rev,v_status='approved')
 ON CONFLICT ON CONSTRAINT future_eligibility_pkey DO UPDATE SET participation_revision=excluded.participation_revision,validated=excluded.validated,category=excluded.category,updated_at=v_now;
 END IF;
 receipt:=jsonb_build_object('id',p_id,'guildId',p_guild,'action',p_action,'revision',next_rev,'replayed',false,'economicIssued',false);
 INSERT INTO guild_activity_private.commands VALUES(p_request,owner_id,p_actor,p_guild,sig,receipt,v_now);
 INSERT INTO public.guild_activity_log(guild_id,actor_traveler_id,event_type,entity_type,entity_id,metadata) VALUES(p_guild,p_actor,'community_'||p_action,'community_activity',p_id,jsonb_build_object('revision',next_rev,'beforeStatus',previous_status,'afterStatus',CASE WHEN p_action IN('state','review') THEN v_status END,'subject',CASE WHEN p_action IN('delegate','review') THEN target END,'reasonDigest',CASE WHEN p_action='review' THEN md5(coalesce(p_data->>'reason','')) END));
 RETURN receipt;
END $function$
;
CREATE OR REPLACE FUNCTION guild_activity_private.workspace(p_actor uuid, p_guild uuid, p_offset integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE own_role text;ids uuid[];staff boolean;
BEGIN
 own_role:=guild_activity_private.actor_role(p_actor,p_guild);staff:=own_role='leader';
 IF p_offset IS NULL OR p_offset<0 OR p_offset>100000 THEN RAISE EXCEPTION 'Invalid page' USING ERRCODE='22023';END IF;
 SELECT coalesce(array_agg(x.id),'{}') INTO ids FROM(SELECT m.id FROM public.guild_missions m WHERE m.guild_id=p_guild AND m.community_protocol=1 AND
 (staff OR guild_activity_private.can_validate(p_actor,m.id) OR(m.status<>'draft' AND (m.audience='all' OR p_actor=ANY(m.target_traveler_ids) OR EXISTS(SELECT 1 FROM public.guild_mission_progress gp WHERE gp.mission_id=m.id AND gp.participant_uid=auth.uid()))))
 ORDER BY m.starts_at NULLS LAST,m.created_at DESC,m.id LIMIT 25 OFFSET p_offset)x;
 RETURN jsonb_build_object('version',1,'guildId',p_guild,'leader',staff,'hasMore',(cardinality(ids)=25),'offset',p_offset,
 'missions',coalesce((SELECT jsonb_agg(jsonb_build_object('id',m.id,'title',m.title,'description',m.description,'objective',m.objective,'instructions',m.instructions,'evidenceCriterion',m.evidence_criterion,'reference',m.bible_reference,'startsAt',m.starts_at,'dueAt',m.due_at,'status',m.status,'revision',m.workspace_revision,'audience',m.audience,'targetIds',CASE WHEN staff THEN to_jsonb(m.target_traveler_ids) ELSE '[]'::jsonb END,
 'kind',d.kind,'meetingId',d.meeting_id,'category',d.category,'theme',d.theme,'meetingType',d.meeting_type,'responsibleId',d.responsible_id,'accessDetails',CASE WHEN staff OR(m.status='published' AND(m.audience='all' OR p_actor=ANY(m.target_traveler_ids))) THEN d.access_details ELSE '' END,'economyTier',CASE WHEN m.metadata->'economy041'->>'contract'='economy041-chest-v1' THEN m.metadata->'economy041'->>'tier' ELSE 'none' END,'futureCategory',d.future_category,'canEdit',staff,'canValidate',guild_activity_private.can_validate(p_actor,m.id),
 'canParticipate',m.status='published' AND (m.audience='all' OR p_actor=ANY(m.target_traveler_ids)) AND(m.starts_at IS NULL OR m.starts_at<=clock_timestamp()) AND(m.due_at IS NULL OR m.due_at>=clock_timestamp()) AND(d.meeting_id IS NULL OR EXISTS(SELECT 1 FROM public.guild_missions parent WHERE parent.id=d.meeting_id AND parent.status='published')))
 ORDER BY m.starts_at NULLS LAST,m.created_at DESC,m.id) FROM public.guild_missions m JOIN guild_activity_private.details d ON d.mission_id=m.id WHERE m.id=ANY(ids)),'[]'::jsonb),
 'progress',coalesce((SELECT jsonb_agg(jsonb_build_object('id',gp.id,'missionId',gp.mission_id,'travelerId',gp.traveler_id,'travelerName',t.name,'own',gp.participant_uid=auth.uid(),'status',gp.status,'revision',gp.community_revision,'submittedAt',gp.submitted_at,'rewardClaimed',gp.reward_claimed_at IS NOT NULL,'approvedAt',gp.approved_at,'reviewNote',gp.review_note)) FROM public.guild_mission_progress gp JOIN public.travelers t ON t.id=gp.traveler_id WHERE gp.mission_id=ANY(ids) AND gp.participant_uid IS NOT NULL AND(gp.participant_uid=auth.uid() OR guild_activity_private.can_validate(p_actor,gp.mission_id))),'[]'::jsonb),
 'members',CASE WHEN staff THEN coalesce((SELECT jsonb_agg(jsonb_build_object('id',t.id,'name',t.name)) FROM public.guild_members gm JOIN public.travelers t ON t.id=gm.traveler_id WHERE gm.guild_id=p_guild AND gm.status='active'),'[]'::jsonb) ELSE '[]'::jsonb END,
 'delegations',coalesce((SELECT jsonb_agg(jsonb_build_object('missionId',d.mission_id,'travelerId',d.traveler_id,'expiresAt',d.expires_at,'active',d.active,'revision',d.revision)) FROM guild_activity_private.delegations d WHERE d.mission_id=ANY(ids) AND(staff OR d.traveler_id=p_actor)),'[]'::jsonb),
 'validations',coalesce((SELECT jsonb_agg(jsonb_build_object('missionId',h.mission_id,'travelerId',h.traveler_id,'reviewerId',h.reviewer_id,'beforeStatus',h.before_status,'afterStatus',h.after_status,'reason',h.reason,'revision',h.revision,'createdAt',h.created_at) ORDER BY h.created_at DESC) FROM guild_activity_private.validation_history h WHERE h.mission_id=ANY(ids) AND guild_activity_private.can_validate(p_actor,h.mission_id)),'[]'::jsonb),
 'history',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC,x.id) FROM(SELECT a.id,a.entity_id,a.event_type,a.actor_traveler_id,a.metadata,a.created_at FROM public.guild_activity_log a WHERE a.guild_id=p_guild AND a.entity_id=ANY(ids) AND a.event_type LIKE 'community_%' AND(staff OR a.actor_traveler_id=p_actor OR a.metadata->>'subject'=p_actor::text OR guild_activity_private.can_validate(p_actor,a.entity_id)) ORDER BY a.created_at DESC,a.id LIMIT 40)x),'[]'::jsonb));
END $function$
;
-- Every helper starts closed. Only the existing wrappers and this limited sale RPC are callable.
REVOKE ALL ON FUNCTION shop_private.immutable_041(),shop_private.random_index_041(integer),shop_private.pool_ready_041(text),shop_private.ready_041(uuid,uuid),shop_private.rate_limit_041(uuid),shop_private.quantity_041(uuid,uuid,text),shop_private.purchase_041(uuid,text,uuid),shop_private.open_041(uuid,text,uuid),shop_private.sell_041(uuid,text,uuid,integer),public.sell_repeated_item(uuid,text,uuid,integer) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION shop_private.sell_041(uuid,text,uuid,integer),public.sell_repeated_item(uuid,text,uuid,integer) TO authenticated;
-- Explicit version negotiation: old clients keep purchase_shop and its receipts.
CREATE FUNCTION public.purchase_expansion_chest(p_actor uuid,p_kind text,p_offer text,p_operation_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
 IF p_kind IS DISTINCT FROM 'chest' THEN RAISE EXCEPTION 'Chest required' USING ERRCODE='22023';END IF;
 RETURN shop_private.purchase_041(p_actor,p_offer,p_operation_id);
END $$;
REVOKE ALL ON FUNCTION public.purchase_expansion_chest(uuid,text,text,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.purchase_expansion_chest(uuid,text,text,uuid),shop_private.purchase_041(uuid,text,uuid) TO authenticated;
